import re
from collections import defaultdict

REPO = "/bench/repo"

# Data layer: store tree + internal storage protos
DATA_LAYER_PREFIXES = (
    "store/",
    "proto/store/",
    "proto/gen/store/",
)

def is_data_layer(path):
    rel = path[len(REPO)+1:] if path.startswith(REPO) else path
    return any(rel.startswith(p) for p in DATA_LAYER_PREFIXES)

def is_excluded(path):
    rel = path[len(REPO)+1:]
    base = os.path.basename(path)
    if base.endswith("_test.go"):
        return True
    if "/test/" in rel and rel.startswith("store/"):
        return True
    if "/vendor/" in rel:
        return True
    if "/proto/gen/" in rel and not rel.startswith("proto/gen/store/"):
        pass  # other gen is fine to include as consumer
    return False

# Persistent entity types: primary Go struct in store/*.go mapped to DB tables
ENTITIES = {
    "Memo": {"struct": "Memo", "proto": ["MemoPayload"]},
    "User": {"struct": "User", "proto": []},
    "Attachment": {"struct": "Attachment", "proto": ["AttachmentPayload", "AttachmentStorageType"]},
    "Inbox": {"struct": "Inbox", "proto": ["Inbox"]},
    "IdentityProvider": {"struct": "IdentityProvider", "proto": ["IdentityProvider"]},
    "InstanceSetting": {"struct": "InstanceSetting", "proto": ["InstanceSetting", "InstanceSettingKey"]},
    "UserSetting": {"struct": "UserSetting", "proto": ["UserSetting"]},
    "MemoRelation": {"struct": "MemoRelation", "proto": []},
    "MemoShare": {"struct": "MemoShare", "proto": []},
    "Reaction": {"struct": "Reaction", "proto": []},
    "UserIdentity": {"struct": "UserIdentity", "proto": []},
}

# Collect go files outside data layer
files_by_pkg = defaultdict(list)
for root, dirs, files in os.walk(os.path.join(REPO, "cmd")):
    for f in files:
        if f.endswith(".go"):
            path = os.path.join(root, f)
            if not is_excluded(path) and not is_data_layer(path):
                pkg = os.path.dirname(path)
                files_by_pkg[pkg].append(path)
for root, dirs, files in os.walk(os.path.join(REPO, "internal")):
    for f in files:
        if f.endswith(".go"):
            path = os.path.join(root, f)
            if not is_excluded(path) and not is_data_layer(path):
                pkg = os.path.dirname(path)
                files_by_pkg[pkg].append(path)
for root, dirs, files in os.walk(os.path.join(REPO, "server")):
    for f in files:
        if f.endswith(".go"):
            path = os.path.join(root, f)
            if not is_excluded(path) and not is_data_layer(path):
                pkg = os.path.dirname(path)
                files_by_pkg[pkg].append(path)

# Also proto/gen/api consumers? api is public API not data layer
for sub in ["proto/gen/api"]:
    p = os.path.join(REPO, sub)
    if os.path.isdir(p):
        for root, dirs, files in os.walk(p):
            for f in files:
                if f.endswith(".go") and not f.endswith("_test.go"):
                    path = os.path.join(root, f)
                    if not is_data_layer(path):
                        pkg = os.path.dirname(path)
                        files_by_pkg[pkg].append(path)

def pkg_imports_store(content):
    return bool(re.search(r'"github.com/usememos/memos/store"', content))

def pkg_imports_storepb(content):
    return bool(re.search(r'"github.com/usememos/memos/proto/gen/store"', content))

results = {}
for entity, info in ENTITIES.items():
    struct_name = info["struct"]
    proto_names = info["proto"]
    matching_pkgs = {}

    for pkg, paths in files_by_pkg.items():
        pkg_content = ""
        for p in paths:
            with open(p) as fh:
                pkg_content += fh.read() + "\n"

        refs = []
        # store.Entity references
        if pkg_imports_store(pkg_content) or f"store.{struct_name}" in pkg_content:
            patterns = [
                rf'\bstore\.{struct_name}\b',
                rf'\*{struct_name}\b',  # within store package only - skip
                rf'\bFind{struct_name}\b',
                rf'\bUpdate{struct_name}\b',
                rf'\bDelete{struct_name}\b',
            ]
            for pat in patterns[:1]:  # primary entity ref
                if re.search(pat, pkg_content):
                    refs.append(f"store.{struct_name}")
                    break
            # Also check Find/Update patterns with store prefix
            for suffix in ["Find", "Update", "Delete"]:
                if re.search(rf'\bstore\.{suffix}{struct_name}\b', pkg_content):
                    refs.append(f"store.{suffix}{struct_name}")

        # storepb references
        if proto_names and (pkg_imports_storepb(pkg_content) or "storepb." in pkg_content):
            for pn in proto_names:
                if re.search(rf'\bstorepb\.{re.escape(pn)}\b', pkg_content):
                    refs.append(f"storepb.{pn}")

        if refs:
            rel_pkg = pkg[len(REPO)+1:]
            matching_pkgs[rel_pkg] = sorted(set(refs))

    results[entity] = matching_pkgs

# Print ranked
ranked = sorted(results.items(), key=lambda x: len(x[1]), reverse=True)
print("=== RANKING (distinct packages outside data layer) ===")
for entity, pkgs in ranked:
    print(f"{entity}: {len(pkgs)} packages")
    for p in sorted(pkgs.keys())[:5]:
        print(f"  - {p} ({', '.join(pkgs[p])})")
    if len(pkgs) > 5:
        print(f"  ... and {len(pkgs)-5} more")
    print()
PYEOF

