perl -e '
use strict; use warnings;
my $REPO = "/bench/repo";
my @PREFIXES = ("store/", "proto/store/", "proto/gen/store/");

sub is_data_layer {
    my ($rel) = @_;
    for my $p (@PREFIXES) { return 1 if index($rel, $p) == 0; }
    return 0;
}
sub is_excluded {
    my ($rel) = @_;
    return 1 if $rel =~ /_test\.go$/;
    return 1 if $rel =~ m{^store/test/};
    return 1 if $rel =~ /\/vendor\//;
    return 0;
}

my %files_by_pkg;
for my $root ("cmd", "internal", "server") {
    my $base = "$REPO/$root";
    next unless -d $base;
    find_go($base);
}
sub find_go {
    my ($dir) = @_;
    opendir my $dh, $dir or return;
    while (my $e = readdir $dh) {
        next if $e eq "." || $e eq "..";
        my $path = "$dir/$e";
        if (-d $path) { find_go($path); next; }
        next unless $e =~ /\.go$/;
        my $rel = substr($path, length($REPO)+1);
        next if is_excluded($rel) || is_data_layer($rel);
        my $pkg = $dir;
        $pkg =~ s|^$REPO/||;
        push @{$files_by_pkg{$pkg}}, $path;
    }
    closedir $dh;
}

my %entities = (
    Memo => { struct => "Memo", proto => ["MemoPayload"] },
    User => { struct => "User", proto => [] },
    Attachment => { struct => "Attachment", proto => ["AttachmentPayload","AttachmentStorageType"] },
    Inbox => { struct => "Inbox", proto => ["Inbox"] },
    IdentityProvider => { struct => "IdentityProvider", proto => ["IdentityProvider"] },
    InstanceSetting => { struct => "InstanceSetting", proto => ["InstanceSetting","InstanceSettingKey"] },
    UserSetting => { struct => "UserSetting", proto => ["UserSetting"] },
    MemoRelation => { struct => "MemoRelation", proto => [] },
    MemoShare => { struct => "MemoShare", proto => [] },
    Reaction => { struct => "Reaction", proto => [] },
    UserIdentity => { struct => "UserIdentity", proto => [] },
);

my %results;
for my $entity (keys %entities) {
    my $struct = $entities{$entity}{struct};
    my @protos = @{$entities{$entity}{proto}};
    for my $pkg (sort keys %files_by_pkg) {
        my $content = "";
        for my $f (@{$files_by_pkg{$pkg}}) {
            open my $fh, "<", $f or next;
            local $/; $content .= <$fh> . "\n"; close $fh;
        }
        my @refs;
        if ($content =~ /\bstore\.$struct\b/) { push @refs, "store.$struct"; }
        for my $pn (@protos) {
            if ($content =~ /\bstorepb\.\Q$pn\E\b/) { push @refs, "storepb.$pn"; }
        }
        if (@refs) { $results{$entity}{$pkg} = \@refs; }
    }
}

print "=== RANKING ===\n";
for my $entity (sort { scalar(keys %{$results{$b}}) <=> scalar(keys %{$results{$a}}) } keys %results) {
    my $n = scalar keys %{$results{$entity}};
    print "$entity: $n packages\n";
    my $i = 0;
    for my $pkg (sort keys %{$results{$entity}}) {
        print "  - $pkg\n";
        last if ++$i >= 8;
    }
    print "  ...\n" if $n > 8;
    print "\n";
}
'

