perl -e '
use strict; use warnings;
my $REPO = "/bench/repo";
my @DATA_PREFIXES = ("store/", "proto/store/", "proto/gen/store/");

sub rel { my ($p)=@_; $p =~ s|^$REPO/||; return $p; }
sub is_data_layer { my ($r)=@_; for (@DATA_PREFIXES){ return 1 if index($r,$_)==0 } 0 }
sub is_excluded {
  my ($r)=@_;
  return 1 if $r =~ /_test\.go$/;
  return 1 if $r =~ m{/(test)/};  # test subdirs
  return 1 if $r =~ m{^web/tests/};
  return 0;
}

my %pkg_files;
for my $scan ("cmd","internal","server") {
  walk("$REPO/$scan");
}
sub walk {
  my ($dir)=@_;
  return unless -d $dir;
  opendir my $dh,$dir or return;
  while(my $e=readdir $dh){
    next if $e eq "."||$e eq "..";
    my $p="$dir/$e";
    if(-d $p){ walk($p); next }
    next unless $e =~ /\.go$/;
    my $r=rel($p);
    next if is_excluded($r)||is_data_layer($r);
    my $pkg=$r; $pkg=~s|/[^/]+$||;
    push @{$pkg_files{$pkg}}, $p;
  }
  closedir $dh;
}

# Entity -> regex patterns for USAGE (not definition)
my %entities = (
  Memo => [qr/\bstore\.Memo\b/, qr/\bstore\.FindMemo\b/, qr/\bstore\.UpdateMemo\b/, qr/\bstore\.DeleteMemo\b/, qr/\bstorepb\.MemoPayload\b/],
  User => [qr/\bstore\.User\b/, qr/\bstore\.FindUser\b/, qr/\bstore\.UpdateUser\b/, qr/\bstore\.DeleteUser\b/, qr/\bstore\.Role\b/],
  Attachment => [qr/\bstore\.Attachment\b/, qr/\bstore\.FindAttachment\b/, qr/\bstore\.UpdateAttachment\b/, qr/\bstore\.DeleteAttachment\b/, qr/\bstorepb\.AttachmentPayload\b/, qr/\bstorepb\.AttachmentStorageType\b/],
  Inbox => [qr/\bstore\.Inbox\b/, qr/\bstore\.FindInbox\b/, qr/\bstore\.UpdateInbox\b/, qr/\bstore\.DeleteInbox\b/, qr/\bstorepb\.Inbox\b/, qr/\bstorepb\.InboxMessage\b/],
  IdentityProvider => [qr/\bstore\.IdentityProvider\b/, qr/\bstore\.FindIdentityProvider\b/, qr/\bstore\.UpdateIdentityProvider\b/, qr/\bstore\.DeleteIdentityProvider\b/, qr/\bstorepb\.IdentityProvider\b/],
  InstanceSetting => [qr/\bstore\.InstanceSetting\b/, qr/\bstore\.FindInstanceSetting\b/, qr/\bstorepb\.InstanceSetting\b/, qr/\bstorepb\.InstanceSettingKey\b/],
  UserSetting => [qr/\bstore\.UserSetting\b/, qr/\bstore\.FindUserSetting\b/, qr/\bstorepb\.UserSetting\b/],
  MemoRelation => [qr/\bstore\.MemoRelation\b/, qr/\bstore\.FindMemoRelation\b/, qr/\bstore\.DeleteMemoRelation\b/],
  MemoShare => [qr/\bstore\.MemoShare\b/, qr/\bstore\.FindMemoShare\b/, qr/\bstore\.DeleteMemoShare\b/],
  Reaction => [qr/\bstore\.Reaction\b/, qr/\bstore\.FindReaction\b/, qr/\bstore\.DeleteReaction\b/],
  UserIdentity => [qr/\bstore\.UserIdentity\b/, qr/\bstore\.FindUserIdentity\b/, qr/\bstore\.DeleteUserIdentity\b/],
);

my %results;
for my $entity (keys %entities) {
  for my $pkg (keys %pkg_files) {
    my $content="";
    for my $f (@{$pkg_files{$pkg}}){
      open my $fh,"<",$f or next; local $/; $content .= <$fh>."\n"; close $fh;
    }
    my @matched;
    for my $re (@{$entities{$entity}}){
      push @matched, $1 if $content =~ /($re)/;
    }
    if(@matched){
      my %u; @matched=grep{!$u{$_}++} @matched;
      $results{$entity}{$pkg}=\@matched;
    }
  }
}

print "Total non-data-layer packages scanned: ", scalar(keys %pkg_files), "\n\n";
for my $entity (sort { (keys %{$results{$b}}) <=> (keys %{$results{$a}}) } keys %entities) {
  my @pkgs = sort keys %{$results{$entity} // {}};
  print "$entity: ", scalar(@pkgs), " packages\n";
  for my $p (@pkgs) {
    my $files = join ", ", map { my $x=$_; $x=~s|^$REPO/||; $x } @{$pkg_files{$p}};
    print "  $p\n";
    # show first matching file evidence
    for my $f (@{$pkg_files{$p}}){
      open my $fh,"<",$f or next; my @lines=<$fh>; close $fh;
      for my $i (0..$#lines){
        for my $re (@{$entities{$entity}}){
          if($lines[$i] =~ $re){
            my $rf=rel($f);
            print "    evidence: $rf:".($i+1)." => ".($lines[$i]=~s/^\s+//r);
            goto NEXT_PKG;
          }
        }
      }
    }
    NEXT_PKG:
  }
  print "\n";
}
'

