my @DATA_PREFIXES = ("store/", "proto/store/", "proto/gen/store/");

sub rel { my ($p)=@_; $p =~ s|^$REPO/||; return $p; }
sub is_data_layer { my ($r)=@_; for (@DATA_PREFIXES){ return 1 if index($r,$_)==0 } 0 }
sub is_excluded {
  my ($r)=@_;
  return 1 if $r =~ /_test\.go$/;
  return 1 if $r =~ m{/(test)/};  # test subdirs
  return 1 if $r =~ m{^web/tests/};
  return 0;
}

