for my $scan ("cmd","internal","server") {
  walk("$REPO/$scan");
}
sub walk {
  my ($dir)=@_;
  return unless -d $dir;
  opendir my $dh,$dir or return;
  while(my $e=readdir $dh){
    next if $e eq "."||$e eq "..";
    my $p="$dir/$e";
    if(-d $p){ walk($p); next }
    next unless $e =~ /\.go$/;
