perl -e '
use strict; use warnings;
my $REPO = "/bench/repo";
my @DATA = ("store/","proto/store/","proto/gen/store/");

sub rel { my($p)=@_; $p=~s|^\Q$REPO\E/||; $p }
sub dl { my($r)=@_; for(@DATA){return 1 if index($r,$_)==0} 0 }
sub ex { my($r)=@_; return 1 if $r=~/_test\.go$/||$r=~m{/(test)/}; 0 }

my %pf;
for my $root ("cmd","internal","server") { walk("$REPO/$root"); }
sub walk {
  my($d)=@_; return unless -d $d;
  opendir my $dh,$d; while(my $e=readdir $dh){
    next if $e eq "."||$e eq "..";
    my $p="$d/$e";
    if(-d $p){walk($p);next}
    next unless $e=~/\.go$/;
    my $r=rel($p); next if ex($r)||dl($r);
    my $pkg=$r; $pkg=~s|/[^/]+$||;
    push @{$pf{$pkg}},$p;
  }
  closedir $dh;
}

# Strict: only store.<Entity> exact type references
my @entities = qw(
  Memo User Attachment Inbox IdentityProvider InstanceSetting UserSetting
  MemoRelation MemoShare Reaction UserIdentity
);
my %pat; $pat{$_} = qr/\bstore\.$_\b/ for @entities;

my (%res, %evidence);
for my $ent (@entities) {
  for my $pkg (keys %pf) {
    for my $f (@{$pf{$pkg}}) {
      open my $fh,"<",$f or next;
      my $i=0;
      while (<$fh>) {
        $i++;
        if (/$pat{$ent}/) {
          $res{$ent}{$pkg}=1;
          $evidence{$ent}{$pkg}="$f:$i" unless $evidence{$ent}{$pkg};
          last;
        }
      }
      close $fh;
      last if $res{$ent}{$pkg};
    }
  }
}

print "Strict count: store.<Entity> only\n";
print "Scanned ", scalar(keys %pf), " packages\n\n";
for my $ent (sort { scalar(keys%{$res{$b}}) <=> scalar(keys%{$res{$a}}) } @entities) {
  my @pkgs = sort keys %{$res{$ent}};
  print "$ent: ", scalar(@pkgs), "\n";
  for my $p (@pkgs) {
    my $ev = $evidence{$ent}{$p}; $ev =~ s|^\Q$REPO\E/||;
    print "  $p ($ev)\n";
  }
  print "\n";
}
'

